                  {cancelaciones.length>0&&<div style={{background:"rgba(249,115,22,0.08)",border:"1px solid rgba(249,115,22,0.25)",borderRadius:10,padding:"10px 16px",display:"flex",alignItems:"center",gap:8,flex:1,minWidth:200}}><span style={{fontSize:18}}>⚠️</span><div><div style={{color:"#f97316",fontWeight:700,fontSize:12}}>{cancelaciones.length} cancelaciones solicitadas</div><div style={{color:"#9ca3af",fontSize:11}}>{cancelaciones.map(c=>c.nombre).join(", ")}</div></div></div>}
                  {totalPendienteGastos>0&&<div style={{background:"rgba(234,179,8,0.08)",border:"1px solid rgba(234,179,8,0.25)",borderRadius:10,padding:"10px 16px",display:"flex",alignItems:"center",gap:8,flex:1,minWidth:200}}><span style={{fontSize:18}}>💸</span><div><div style={{color:"#eab308",fontWeight:700,fontSize:12}}>Gasto pendiente</div><div style={{color:"#9ca3af",fontSize:11}}>{fmt(totalPendienteGastos)}€ por pagar</div></div></div>}
